#!/usr/bin/env bash
# Shared paths/constants for bin/start.sh and bin/stop.sh -- sourced, not
# executed directly.

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BACKEND_DIR="$REPO_ROOT/backend"
FRONTEND_DIR="$REPO_ROOT/frontend"

# PID files live outside backend/ and frontend/ so they survive independent
# of either app's own log/build directories -- both of which already get
# wiped/regenerated by normal dev workflows (`.next/`, log rotation).
PID_DIR="$REPO_ROOT/.run"
BACKEND_PID_FILE="$PID_DIR/backend.pid"
FRONTEND_PID_FILE="$PID_DIR/frontend.pid"

# uvicorn_dev.log already existed as an ad-hoc filename in backend/logs/
# before this script -- reusing it makes it canonical instead of adding a
# second, differently-named log for the same process.
BACKEND_LOG="$BACKEND_DIR/logs/uvicorn_dev.log"
FRONTEND_LOG_DIR="$FRONTEND_DIR/logs"
FRONTEND_LOG="$FRONTEND_LOG_DIR/next_dev.log"

# 8002, not uvicorn's default 8000 -- frontend/next.config.ts hardcodes its
# API rewrite ("/api/:path*") to http://localhost:8002, so the backend must
# bind that exact port for the frontend to reach it at all. Both ports are
# overridable via env var for a one-off run (e.g. an alternate port to test
# start.sh without colliding with an already-running instance) without
# touching this file.
BACKEND_HOST="${BACKEND_HOST:-0.0.0.0}"
BACKEND_PORT="${BACKEND_PORT:-8002}"
FRONTEND_PORT="${FRONTEND_PORT:-3100}"

BACKEND_HEALTH_URL="http://localhost:${BACKEND_PORT}/api/health"
FRONTEND_URL="http://localhost:${FRONTEND_PORT}"

# Process-group leader is alive if `kill -0` on the negated PID succeeds --
# used by both start.sh (refuse to double-start) and stop.sh.
pid_group_alive() {
  local pid="$1"
  [[ -n "$pid" ]] && kill -0 -- "-$pid" 2>/dev/null
}
